def find_zero(xs: list):
    a = xs[-1]
    b = xs[-2]
    # Use the quadratic formula for the case of a quadratic polynomial
    if len(xs) == 2:
        return -b / (2 * a)
    elif len(xs) == 4:
        # For cubic polynomials, we can use a numerical method like Newton's method
        def poly_derivative(coeffs):
            return [i * coeffs[i] for i in range(1, len(coeffs))]

        def newton_method(coeffs, x0, iterations=1000):
            for _ in range(iterations):
                f_x0 = poly(coeffs, x0)
                f_prime_x0 = poly(poly_derivative(coeffs), x0)
                if f_prime_x0 == 0:
                    break
                x0 -= f_x0 / f_prime_x0
            return x0

        return newton_method(xs, 0)
    else:
        raise ValueError("The number of coefficients must be even.")

